export type CustomerOrderFullCopy = CustomerOrderCopy & Record<keyof typeof extraEnglish, string>;

export function customerOrderCopy(locale: string): CustomerOrderFullCopy {
  const key: CustomerCopyLocale = Object.prototype.hasOwnProperty.call(CUSTOMER_ORDER_COPY, locale)
    ? locale as CustomerCopyLocale
    : "en";
  return { ...CUSTOMER_ORDER_COPY[key], ...extra[key] };
}
